window.CatalogBlock={name:"CatalogBlock",props:{dataId:{type:String,default:""},dataUrl:{type:String,required:!0},title:{type:String,default:"Каталог товаров"},sub:{type:String,default:""},linkText:{type:String,default:"Весь каталог"},linkHref:{type:String,default:"catalog_in.html"},effect:{type:String,default:"flip"},enter:{type:String,default:"rise"},cols:{type:Number,default:3}},data:function(){return{cats:[],loading:!0,error:!1,_received:!1}},computed:{subParas:function(){return(this.sub||"").split("\n").filter(function(t){return""!==t.trim()})}},created:function(){this.load()},methods:{load:function(){var t=this,e=0,a=function(){e++,fetch(t.dataUrl).then(function(t){return t.json()}).then(function(e){t.recv(e)}).catch(function(){e<3?setTimeout(a,500*e):t.fail()})};if(/\.json$/i.test(t.dataUrl))a();else{var n=function(e){var a=e.detail;a&&a.id===t.dataId&&(window.removeEventListener("t1:catalog",n),t.recv(a.list||[]))};window.addEventListener("t1:catalog",n);var i=document.createElement("script");i.src=t.dataUrl,i.onload=function(){t._received||t.fail()},i.onerror=function(){t.fail()},document.head.appendChild(i)}},recv:function(t){var e=this;e._received=!0,e.cats=t||[],e.loading=!1,e.cats.length||(e.error=!0)},fail:function(){this.loading=!1,this.error=!0}},template:'\n<div class="catalog" aria-label="Каталог товаров">\n    <div class="section-head" v-if="title || (subParas && subParas.length) || linkText">\n      <div>\n        <h2 class="section-title" v-if="title">{{ title }}</h2>\n        <p v-for="(para, i) in subParas" :key="\'sub-\' + i" class="section-sub">{{ para }}</p>\n      </div>\n      <a v-if="linkText" class="section-head__link" :href="linkHref">{{ linkText }}\n        <svg class="icon icon-arrow-right" aria-hidden="true"><use href="#i-arrow-right"></use></svg>\n      </a>\n    </div>\n\n    <p v-if="loading" class="goods-status">Загружаем категории…</p>\n    <p v-else-if="error" class="goods-status goods-status--error">Не удалось загрузить категории.</p>\n\n    <div v-else class="cat-grid" itemscope itemtype="https://schema.org/ItemList"\n         :class="[\'cat-grid--\' + effect, \'cat-enter--\' + enter]"\n         :style="{ \'--catalog-cols\': cols }">\n      <a class="cat-card" itemprop="itemListElement" itemscope itemtype="https://schema.org/ListItem"\n         v-for="(c, i) in cats" :key="c.id" :href="c.url" :style="{ \'--i\': i }">\n        <meta itemprop="position" :content="String(i + 1)">\n        <meta itemprop="url" :content="c.url">\n        <div class="cat-card__inner">\n          <div class="cat-card__face cat-card__face--front">\n            <img v-if="c.photo" class="cat-card__img" :src="c.photo" :alt="c.header" loading="lazy">\n            <h3 class="cat-card__name" itemprop="name">{{ c.header }}</h3>\n          </div>\n          <div class="cat-card__face cat-card__face--back">\n            <h3 class="cat-card__name">{{ c.header }}</h3>\n            <p class="cat-card__desc">{{ c.body }}</p>\n            <span class="cat-card__more">Смотреть\n              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M5 12h14M13 6l6 6-6 6"/></svg>\n            </span>\n          </div>\n        </div>\n      </a>\n    </div>\n</div>'};